-- Check if there's a rank column or APE (Average Position Error) related concept
-- Let me check the performance_and_safety table for any rank-related fields
SELECT * FROM performance_and_safety LIMIT 1;

-- Let me check the later dates too
SELECT instdateval, COUNT(*) as cnt FROM robot_details 
GROUP BY instdateval ORDER BY instdateval DESC LIMIT 20;

-- Now let me check the age calculation. "Large Robot Age" = age > 1 year from instdateval
-- Let me see what date we should use for comparison (probably current date or latest record date)
SELECT MAX(rects) FROM robot_record;

-- All robots have age > 1 year based on CURRENT_DATE. But the user said "large Robot Age" = > 1 year.
-- Let me check if any robot has age <= 1 year
SELECT COUNT(*) FROM robot_details WHERE AGE(CURRENT_DATE, instdateval) <= INTERVAL '1 year';

-- Let me check if there's an "age" column in any table
SELECT table_name, column_name FROM information_schema.columns 
WHERE column_name LIKE '%age%' OR column_name LIKE '%ape%';
